//! The desktop bridge: every Tauri command forwards one [`ToolkitCommand`] to the manager,
//! and every manager event becomes a typed Tauri event. Commands speak the wire types in
//! [`crate::frontend::dto`], never the core's own types.
//!
//! The TypeScript bindings for these commands and events (`apps/tauri/src/bindings.ts`) are
//! generated by `tauri-specta`: every debug launch rewrites them and the
//! `committed_bindings_are_current` test fails when they are stale.

use crate::frontend::dto::{
    Activity, CapturedCalibrationReading, DeviceCalibrationData, FrontendBalanceBoardEvent,
    FrontendCalibrationReading, GeneralSettings, LastSessionInformation, MacAddress,
    NintendoDevice, ReplayInformation, SessionActivityState, SessionInformation, SessionSettings,
    TimelineBlock, User, UserPageInformation,
};
use serde::{Deserialize, Serialize};
use specta::Type;
use specta_typescript::{Typescript, semantic};
use std::path::PathBuf;
use tauri::ipc::Channel;
use tauri::{AppHandle, State};
use tauri_specta::{Builder, ErrorHandlingMode, Event, collect_commands, collect_events};
use tokio::sync::mpsc::{Receiver, Sender};
use tokio::sync::{mpsc, oneshot};
use toolkit_core::actors::balance_board_actor::BoardAction;
use toolkit_core::actors::bluetooth_service::{BluetoothCommand, BluetoothPeripheral};
use toolkit_core::actors::toolkit_service::{ToolkitCommand, ToolkitResponse};

/// Where the generated TypeScript bindings live, relative to this crate.
const BINDINGS_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../src/bindings.ts");

pub struct AppState {
    pub manager_tx: Sender<ToolkitCommand>,
}

/// Every command and event the frontend can use, in one place so the invoke handler and
/// the generated bindings cannot disagree.
fn specta_builder() -> Builder<tauri::Wry> {
    Builder::<tauri::Wry>::new()
        // The frontend treats a failed command like a rejected promise, as `invoke` did.
        .error_handling(ErrorHandlingMode::Throw)
        // MAC addresses are `u64`; they fit in a JavaScript number (48 bits).
        .dangerously_cast_bigints_to_number()
        // Floats are plain `number`s: serde_json would turn a NaN into `null`, but the
        // pipeline never emits one and the previous hand-written types assumed the same.
        .semantic_types(semantic::Configuration::empty().enable_lossless_floats())
        // Nothing serializes differently from how it deserializes, so one type per struct.
        .disable_serde_phases()
        .commands(collect_commands![
            settings_get_settings,
            settings_set_settings,
            user_page_information,
            user_select_user,
            user_create,
            user_update,
            user_delete,
            user_measure_weight,
            devices_get_selected_devices,
            devices_fetch_all_devices,
            devices_scan_without_timeout,
            devices_cancel_scan,
            devices_is_scanning,
            devices_select_device,
            devices_unselect_device,
            devices_update_device_name,
            devices_remove_device,
            devices_identify_device,
            devices_tare_device,
            devices_start_calibration_stream,
            devices_stop_calibration_stream,
            devices_submit_calibration,
            session_start_session,
            session_stop_session,
            session_information,
            session_update_session_configuration,
            session_activity_state,
            session_tare_devices,
            replay_start_replay,
            replay_stop_replay,
            replay_information,
            replay_update,
            replay_load_file,
            replay_clear_replay,
            replay_load_last_session_info,
            activity_get_available_time_blocks,
            activity_get_activities,
            activity_get_activity,
            activity_update_activity,
            activity_reset_activity_to_default,
        ])
        .events(collect_events![
            NewBoard,
            BoardDisconnected,
            SessionStarted,
            SessionCompleted,
            ReplayCompleted,
            SessionActivityChanged,
        ])
}

fn typescript() -> Typescript {
    Typescript::default().header(
        "// @ts-nocheck\n// Generated by tauri-specta from apps/tauri/src-tauri/src/frontend/tauri.rs. Do not edit.\n",
    )
}

pub fn initialize(manager_tx: Sender<ToolkitCommand>, manager_rx: Receiver<ToolkitResponse>) {
    let builder = specta_builder();

    #[cfg(debug_assertions)]
    if let Err(e) = builder.export(typescript(), BINDINGS_PATH) {
        log::error!("Failed to export the TypeScript bindings to {BINDINGS_PATH}: {e}");
    }

    tauri::Builder::default()
        .plugin(tauri_plugin_dialog::init())
        .invoke_handler(builder.invoke_handler())
        .setup(move |app| {
            builder.mount_events(app);
            forward_manager_events(app.handle().clone(), manager_rx);

            let monitor_dimensions = app
                .primary_monitor()
                .ok()
                .flatten()
                .map(|monitor| {
                    let size = monitor.size();
                    (size.width as f64, size.height as f64)
                })
                .or_else(|| {
                    app.available_monitors().ok().and_then(|monitors| {
                        monitors.into_iter().next().map(|monitor| {
                            let size = monitor.size();
                            (size.width as f64, size.height as f64)
                        })
                    })
                });

            let (initial_width, initial_height) = monitor_dimensions
                .map(|(width, height)| (width * 0.55, height * 0.6))
                .unwrap_or((800.0, 600.0));

            tauri::WebviewWindowBuilder::new(app.handle(), "main", tauri::WebviewUrl::default())
                .title("The Balance Toolkit")
                .resizable(true)
                .maximizable(true)
                .inner_size(initial_width, initial_height)
                .build()?;

            Ok(())
        })
        .manage(AppState { manager_tx })
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

// --- EVENTS (manager -> frontend) ---

#[derive(Serialize, Deserialize, Debug, Clone, Type, Event)]
#[serde(rename_all = "camelCase")]
struct NewBoard {
    mac_address: MacAddress,
}

#[derive(Serialize, Deserialize, Debug, Clone, Type, Event)]
#[serde(rename_all = "camelCase")]
struct BoardDisconnected {
    mac_address: MacAddress,
}

#[derive(Serialize, Deserialize, Debug, Clone, Type, Event)]
struct SessionStarted;

#[derive(Serialize, Deserialize, Debug, Clone, Type, Event)]
struct SessionCompleted;

#[derive(Serialize, Deserialize, Debug, Clone, Type, Event)]
struct ReplayCompleted;

#[derive(Serialize, Deserialize, Debug, Clone, Type, Event)]
struct SessionActivityChanged;

/// Turns manager events into Tauri events. A failed emit (the windows are closing) is
/// logged rather than unwrapped: the release profile aborts on panic, which would take a
/// running recording down with it.
fn forward_manager_events(app: AppHandle, mut manager_rx: Receiver<ToolkitResponse>) {
    tokio::spawn(async move {
        while let Some(event) = manager_rx.recv().await {
            let result = match event {
                ToolkitResponse::NewDeviceFound(mac_address) => NewBoard { mac_address }.emit(&app),
                ToolkitResponse::BoardDisconnected(mac_address) => {
                    BoardDisconnected { mac_address }.emit(&app)
                }
                ToolkitResponse::SessionStarted => SessionStarted.emit(&app),
                ToolkitResponse::SessionCompleted => SessionCompleted.emit(&app),
                ToolkitResponse::ReplayCompleted => ReplayCompleted.emit(&app),
                ToolkitResponse::SessionActivityChanged => SessionActivityChanged.emit(&app),
            };
            if let Err(e) = result {
                log::warn!("Failed to forward a toolkit event to the frontend: {e}");
            }
        }
    });
}

// --- HELPERS ---

/// One request/response round trip to the manager.
async fn ask<T>(
    state: &State<'_, AppState>,
    build: impl FnOnce(oneshot::Sender<T>) -> ToolkitCommand,
) -> Result<T, String> {
    toolkit_core::request(&state.manager_tx, build)
        .await
        .map_err(|e| format!("{e:#}"))
}

/// A fire-and-forget command to the manager.
async fn tell(state: &State<'_, AppState>, command: ToolkitCommand) -> Result<(), String> {
    toolkit_core::send(&state.manager_tx, command)
        .await
        .map_err(|e| format!("{e:#}"))
}

fn map_all<A, B: From<A>>(items: Vec<A>) -> Vec<B> {
    items.into_iter().map(Into::into).collect()
}

/// Bridges an internal `mpsc` stream to a Tauri channel, mapping each item. Stops when
/// the frontend drops the channel.
fn forward_to_channel<In, Out>(
    channel: Channel<Out>,
    map: impl Fn(In) -> Out + Send + 'static,
) -> Sender<In>
where
    In: Send + 'static,
    Out: Send + Sync + Clone + Serialize + 'static,
{
    // Deep enough to ride out a webview stall of a few seconds at two boards x 100 Hz.
    // Producers skip samples for a full channel rather than dropping the frontend entirely.
    let (tx, mut rx) = mpsc::channel(2048);
    tokio::spawn(async move {
        while let Some(item) = rx.recv().await {
            if channel.send(map(item)).is_err() {
                log::debug!("Frontend channel closed");
                break;
            }
        }
    });
    tx
}

