// --- USERS ---

#[tauri::command]
#[specta::specta]
async fn user_page_information(state: State<'_, AppState>) -> Result<UserPageInformation, String> {
    let users = ask(&state, |response| ToolkitCommand::GetUsers { response }).await?;
    let session = ask(&state, |response| ToolkitCommand::SessionInformation {
        response,
    })
    .await?;
    Ok(UserPageInformation::new(users, session))
}

