#[tauri::command]
#[specta::specta]
async fn user_measure_weight(
    state: State<'_, AppState>,
    channel: Channel<f64>,
    mac_address: MacAddress,
) -> Result<(), String> {
    let frontend_channel = forward_to_channel(channel, |weight| weight);
    tell(
        &state,
        ToolkitCommand::MeasureWeight {
            frontend_channel,
            mac_address,
        },
    )
    .await
}

