#[tauri::command]
#[specta::specta]
async fn devices_scan_without_timeout(state: State<'_, AppState>) -> Result<(), String> {
    // Flow: First we connect via bluetooth, then we connect via HID.
    let (new_bluetooth_tx, mut new_bluetooth_rx) = mpsc::channel::<BluetoothPeripheral>(10);
    let manager_tx = state.manager_tx.clone();
    tokio::spawn(async move {
        while let Some(device) = new_bluetooth_rx.recv().await {
            let command = ToolkitCommand::Connect {
                mac_address: device.mac_address,
            };
            if manager_tx.send(command).await.is_err() {
                log::warn!("The toolkit manager stopped; ending the scan forwarder");
                break;
            }
        }
    });

    ask(&state, |response| {
        ToolkitCommand::BluetoothAction(BluetoothCommand::StartScanAndPair {
            response_stream: new_bluetooth_tx,
            response,
        })
    })
    .await
}

