#[cfg(test)]
mod tests {
    use super::*;

    fn export_to_string() -> String {
        let dir = std::env::temp_dir().join(format!("tbt-bindings-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("bindings.ts");
        specta_builder().export(typescript(), &path).unwrap();
        let bindings = std::fs::read_to_string(&path).unwrap();
        let _ = std::fs::remove_dir_all(dir);
        bindings
    }

    /// Regenerates `apps/tauri/src/bindings.ts`: `mise run gen:bindings`.
    #[test]
    #[ignore = "writes the committed bindings; run explicitly"]
    fn export_bindings() {
        std::fs::write(BINDINGS_PATH, export_to_string()).unwrap();
    }

    #[test]
    fn committed_bindings_are_current() {
        let committed = std::fs::read_to_string(BINDINGS_PATH).unwrap_or_default();
        assert!(
            committed == export_to_string(),
            "apps/tauri/src/bindings.ts is stale; run `mise run gen:bindings`"
        );
    }
}
